<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { api, hasRole } from '../api'
import ExamAudience from '../components/ExamAudience.vue'
type Question = { id: number; type: string; stem: string; courseCode: string; chapter?: string; status: string; difficulty: number }
type Item = { questionId: number; points: number; position: number }
type Exam = { makeupSourceExamId?: number | null;  id: number; title: string; courseCode: string | null; chapters?: string[]; description: string; durationMinutes: number; totalScore: number; passScore: number; startTime: string | null; endTime: string | null; status: string; allowRetake: boolean; maxAttempts: number; shuffleQuestions: boolean; basicAntiCheat: boolean; wrongQuestionPaper: boolean; wrongQuestionLimit: number; assignedCandidateCount: number; questionCount: number; questions?: Item[]; allWrongQuestions?: boolean; audienceMode?: string; audienceUserIds?: number[]; audienceMajors?: string[] }
const typeNames: Record<string, string> = { SINGLE_CHOICE: '单选题', MULTIPLE_CHOICE: '多选题', TRUE_FALSE: '判断题', FILL_BLANK: '填空题', SHORT_ANSWER: '简答题', CALCULATION: '计算题', IMAGE_CASE: '案例题', ESSAY: '大题' }
const randomTypes = ['SINGLE_CHOICE', 'MULTIPLE_CHOICE', 'TRUE_FALSE'] as const
const statusNames: Record<string, string> = { DRAFT: '草稿', PUBLISHED: '已发布', CLOSED: '已关闭', CANCELLED: '已取消' }
const canManage = hasRole('SYSTEM_ADMIN', 'DEPARTMENT_LEADER', 'TRAINING_ADMIN', 'SPECIALIST')
const canPublish = hasRole('SYSTEM_ADMIN', 'DEPARTMENT_LEADER', 'TRAINING_ADMIN')
const exams = ref<Exam[]>([]), questions = ref<Question[]>([]), error = ref(''), message = ref(''), loading = ref(false), busy = ref(false), editingId = ref<number | null>(null), editorOpen = ref(false)
const search = ref(''), typeFilter = ref(''), examFilter = ref(''), selectionPage = ref(1)
const selected = ref<Record<number, number>>({})
const selectedChapters = ref<string[]>([])
const defaults = () => ({ title: '', courseCode: '', description: '', durationMinutes: 90, totalScore: 100, passScore: 90, startTime: '', endTime: '', allowRetake: false, maxAttempts: 1, shuffleQuestions: true, basicAntiCheat: true, wrongQuestionPaper: false, wrongQuestionLimit: 20, allWrongQuestions: false, audienceMode:'ALL', audienceUserIds:[] as number[], audienceMajors:[] as string[] })
const makeupSource = ref<number|null>(null)
const form = reactive(defaults()), random = reactive({ SINGLE_CHOICE: 0, MULTIPLE_CHOICE: 0, TRUE_FALSE: 0, points: 5 })
const activeQuestions = computed(() => questions.value.filter(q => q.status === 'ACTIVE' && typeNames[q.type]))
const courses = computed(() => [...new Set(activeQuestions.value.map(q => q.courseCode))].sort())
const courseChapters = computed(() => [...new Set(activeQuestions.value.filter(q => q.courseCode === form.courseCode).map(q => q.chapter || '未分章'))].sort())
const inScope = (q: Question) => !selectedChapters.value.length || selectedChapters.value.includes(q.chapter || '未分章')
const eligible = computed(() => activeQuestions.value.filter(q => (!typeFilter.value || q.type === typeFilter.value) && (!form.courseCode || q.courseCode === form.courseCode) && inScope(q) && q.stem.includes(search.value.trim())))
const pages = computed(() => Math.max(1, Math.ceil(eligible.value.length / 15)))
const visible = computed(() => eligible.value.slice((Math.min(selectionPage.value, pages.value) - 1) * 15, Math.min(selectionPage.value, pages.value) * 15))
const totalPoints = computed(() => Object.values(selected.value).reduce((sum, p) => sum + (Number(p) || 0), 0))
const selectedCount = computed(() => Object.keys(selected.value).length)
const visibleExams = computed(() => exams.value.filter(e => !examFilter.value || e.status === examFilter.value))
function reason(e: unknown) { return e instanceof Error ? e.message : '操作失败，请重试' }
function date(value: string | null) { return value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '不限' }
function local(value: string | null) { if (!value) return ''; const d = new Date(value); return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 16) }
async function load() { loading.value = true; try { const result = await Promise.all([api<Exam[]>('/api/exams'), canManage ? api<Question[]>('/api/questions') : Promise.resolve([] as Question[])]); exams.value = result[0]; questions.value = result[1] } catch (e) { error.value = reason(e) } finally { loading.value = false } }
function create() { makeupSource.value=null; Object.assign(form, defaults()); selected.value = {}; selectedChapters.value = []; editingId.value = null; editorOpen.value = true; error.value = ''; message.value = '' }
async function edit(exam: Exam) { busy.value = true; error.value = ''; try { const data = await api<Exam>(`/api/exams/${exam.id}`); makeupSource.value=data.makeupSourceExamId??null; const items = (data.questions || []).sort((a,b) => a.position - b.position); const inferredCourse = questions.value.find(q => q.id === items[0]?.questionId)?.courseCode || ''; Object.assign(form, defaults(), data, { courseCode: data.courseCode || inferredCourse, startTime: local(data.startTime), endTime: local(data.endTime) }); selectedChapters.value = data.chapters || []; selected.value = Object.fromEntries(items.map(q => [q.questionId, q.points])); editingId.value = exam.id; editorOpen.value = true } catch (e) { error.value = reason(e) } finally { busy.value = false } }
async function makeup(exam:Exam){busy.value=true;error.value='';try{const created=await api<Exam>('/api/exams/'+exam.id+'/makeup',{method:'POST'});await load();await edit(created);message.value='已新建补考草稿并自动筛选未及格学员，请设置考试时间后发布。'}catch(e){error.value=reason(e)}finally{busy.value=false}}
function changeCourse() { selected.value = {}; selectedChapters.value = []; selectionPage.value = 1; message.value = form.courseCode ? `已切换到“${form.courseCode}”题库，请重新选择试题。` : '' }
function toggle(id: number, enabled: boolean) { if (enabled) selected.value[id] = random.points; else delete selected.value[id] }
function availableCount(type: string) { return activeQuestions.value.filter(q => q.courseCode === form.courseCode && q.type === type && inScope(q)).length }
function draw() {
  error.value = ''; try {
    if (!form.courseCode) throw new Error('请先选择考试课程')
    const pool = activeQuestions.value.filter(q => q.courseCode === form.courseCode && inScope(q))
    const next: Record<number, number> = {}
    if (!Number.isInteger(random.points) || random.points < 1) throw new Error('每题分值必须为正整数')
    for (const type of randomTypes) {
      const count = Number(random[type as 'SINGLE_CHOICE' | 'MULTIPLE_CHOICE' | 'TRUE_FALSE'])
      if (!Number.isInteger(count) || count < 0) throw new Error('抽题数量须为非负整数')
      const available = pool.filter(q => q.type === type)
      if (count > available.length) throw new Error(`${typeNames[type]}只有 ${available.length} 道可用题，请调整数量或课程筛选`)
      for (let i = available.length - 1; i > 0; i--) { const bytes = new Uint32Array(1); crypto.getRandomValues(bytes); const j = bytes[0] % (i + 1); [available[i], available[j]] = [available[j], available[i]] }
      available.slice(0, count).forEach(q => { next[q.id] = random.points })
    }
    if (!Object.keys(next).length) throw new Error('请至少设置一种题型的抽题数量')
    selected.value = next; message.value = '已抽取题目，可继续手工调整。保存后试卷题目固定。'
  } catch (e) { error.value = reason(e) }
}
async function save() {
  busy.value = true; error.value = ''; message.value = ''
  try {
    if (!form.wrongQuestionPaper && !selectedCount.value) throw new Error('请至少选择一道试题')
    if (!form.wrongQuestionPaper && Object.values(selected.value).some(p => !Number.isInteger(Number(p)) || Number(p) < 1)) throw new Error('每题分值必须为正整数')
    if (!form.wrongQuestionPaper && totalPoints.value !== Number(form.totalScore)) throw new Error(`当前试题合计 ${totalPoints.value} 分，必须与总分 ${form.totalScore} 分一致`)
    if (form.passScore > form.totalScore) throw new Error('及格分不能高于总分')
    if (form.startTime && form.endTime && new Date(form.endTime) <= new Date(form.startTime)) throw new Error('结束时间必须晚于开始时间')
    const input = { title: form.title, courseCode: form.courseCode, chapters: selectedChapters.value, description: form.description, durationMinutes: Number(form.durationMinutes), totalScore: Number(form.totalScore), passScore: Number(form.passScore), startTime: form.startTime ? new Date(form.startTime).toISOString() : null, endTime: form.endTime ? new Date(form.endTime).toISOString() : null, allowRetake: form.allowRetake, maxAttempts: form.allowRetake ? Number(form.maxAttempts) : 1, shuffleQuestions: form.shuffleQuestions, basicAntiCheat: form.basicAntiCheat, wrongQuestionPaper: form.wrongQuestionPaper, wrongQuestionLimit: Number(form.wrongQuestionLimit), allWrongQuestions: form.wrongQuestionPaper && form.allWrongQuestions, audienceMode: form.audienceMode, audienceUserIds: form.audienceUserIds, audienceMajors: form.audienceMajors, questions: form.wrongQuestionPaper ? [] : Object.entries(selected.value).map(([id, points], i) => ({ questionId: Number(id), points: Number(points), position: i + 1 })) }
    await api(`/api/exams${editingId.value ? '/' + editingId.value : ''}`, { method: editingId.value ? 'PUT' : 'POST', body: JSON.stringify(input) }); editorOpen.value = false; message.value = '考试草稿已保存。确认后点击“发布”，考生即可看到考试。'; await load()
  } catch (e) { error.value = reason(e) } finally { busy.value = false }
}
async function action(exam: Exam, operation: 'publish' | 'close') {
  if (operation === 'close' && !window.confirm(`关闭“${exam.title}”后，正在进行的答卷将按已保存答案交卷，且不能继续补考。确认关闭？`)) return
  busy.value = true; error.value = ''; try { await api(`/api/exams/${exam.id}/${operation}`, { method: 'POST' }); message.value = operation === 'publish' ? '考试已发布，考生登录后可查看并参加。' : '考试已关闭'; await load() } catch (e) { error.value = reason(e) } finally { busy.value = false }
}
async function cancelExam(exam: Exam) {
  const reasonText = window.prompt('取消考试后，在考答卷停止作答，已保存记录保留并从成绩分析中排除。请填写取消原因：')
  if (!reasonText?.trim()) return
  busy.value = true; error.value = ''
  try { await api('/api/exams/' + exam.id + '/cancel', { method: 'POST', body: JSON.stringify({ reason: reasonText }) }); await load(); message.value = '考试已取消，记录已保留' } catch (e) { error.value = reason(e) } finally { busy.value = false }
}
onMounted(load)
</script>
<template>
  <div class="page-head"><div><span class="eyebrow dark">EXAM OPERATIONS</span><h1>考试与组卷</h1><p>编写试卷、设置考试时间，确认后向考生发布。</p></div><button v-if="canManage" class="primary-button small" @click="create">＋ 创建考试</button></div>
  <div v-if="error" class="notice error" role="alert">{{ error }}</div><div v-if="message" class="notice" role="status">{{ message }}</div>
  <article v-if="editorOpen" class="panel"><div class="panel-head"><h3>{{ editingId ? '编辑考试草稿' : '新建考试' }}</h3><button class="link-button" @click="editorOpen = false">收起</button></div>
    <form class="exam-form" @submit.prevent="save"><div class="form-grid two"><label>考试名称<input v-model="form.title" required maxlength="200" placeholder="例如：流体力学阶段考试" /></label><label>考试课程<select v-model="form.courseCode" required @change="changeCourse"><option value="" disabled>请选择课程题库</option><option v-for="course in courses" :key="course" :value="course">{{ course }}</option></select></label></div><label>考试说明<textarea v-model="form.description" rows="3" placeholder="填写考试范围、注意事项等，考生可见" /></label>
      <section v-if="!form.wrongQuestionPaper || !form.allWrongQuestions" class="scope-card">
        <div class="scope-heading"><div><span class="step-mark">01</span><strong>选择考试范围</strong></div><small>不选择章节时，默认覆盖该课程全部章节</small></div>
        <div v-if="!form.courseCode" class="scope-empty">请先选择考试课程</div>
        <div v-else-if="!courseChapters.length" class="scope-empty">该课程暂时没有可用章节</div>
        <div v-else class="chapter-options"><label v-for="chapter in courseChapters" :key="chapter" :class="{ active: selectedChapters.includes(chapter) }"><input v-model="selectedChapters" type="checkbox" :value="chapter" />{{ chapter }}</label></div>
      </section>
      <section class="mode-card">
        <div class="scope-heading"><div><span class="step-mark">02</span><strong>选择组卷方式</strong></div></div>
        <div class="mode-options"><label :class="{ active: !form.wrongQuestionPaper }"><input v-model="form.wrongQuestionPaper" type="radio" :value="false" /><span><strong>统一试卷</strong><small>所有考生使用同一套固定试题</small></span></label><label :class="{ active: form.wrongQuestionPaper }"><input v-model="form.wrongQuestionPaper" type="radio" :value="true" /><span><strong>个人考试错题卷</strong><small>仅从每位学员尚未消除的考试错题中独立组卷</small></span></label></div>
        <div v-if="form.wrongQuestionPaper" class="checks"><button type="button" class="secondary-button" :aria-pressed="form.allWrongQuestions" @click="form.allWrongQuestions = !form.allWrongQuestions; selectedChapters = []">{{ form.allWrongQuestions ? '已选择当前课程全部考试错题 · 点击取消' : '选择个人全部考试错题' }}</button></div><label v-if="form.wrongQuestionPaper && !form.allWrongQuestions" class="wrong-limit">每人最多抽取题数<input v-model.number="form.wrongQuestionLimit" type="number" min="1" max="200" required /></label>
      </section>
      <div class="form-grid"><label>总分<input v-model.number="form.totalScore" type="number" min="1" max="10000" required /></label><label>及格分<input v-model.number="form.passScore" type="number" min="0" :max="form.totalScore" required /></label><label>时长（分钟）<input v-model.number="form.durationMinutes" type="number" min="1" max="1440" required /></label><p class="hint">每位学员每场仅一次作答，补考另开考试。</p></div>
      <div class="form-grid two"><label>开放时间（留空立即开放）<input v-model="form.startTime" type="datetime-local" /></label><label>截止时间（留空不限制日期）<input v-model="form.endTime" type="datetime-local" /></label></div>
      <div class="checks"><label><input v-model="form.shuffleQuestions" type="checkbox" /> 打乱题目顺序</label><label><input v-model="form.basicAntiCheat" type="checkbox" /> 记录考试切屏次数</label></div>
      <p v-if="makeupSource" class="notice">本场是考试 #{{makeupSource}} 的补考，发布时自动重新筛选原场已判卷且未及格的学员。缺考、待判卷、已通过和停用人员不纳入。</p><ExamAudience :read-only="Boolean(makeupSource)" :key="editingId??'new'" v-model:mode="form.audienceMode" v-model:user-ids="form.audienceUserIds" v-model:majors="form.audienceMajors" /><div class="notice">客观题交卷后自动判分；试卷含简答题、大题等主观题时，整份成绩在超级管理员完成判卷后公布。</div>
      <section v-if="form.wrongQuestionPaper" class="personal-paper-preview"><span class="personal-icon">↻</span><div><h3>发布时生成个人专属试卷</h3><p>系统将按{{ form.allWrongQuestions ? '当前课程全部章节' : '上方课程和章节范围' }}，读取每位学员当前的考试错题库，{{ form.allWrongQuestions ? '选入当前课程全部章节的待销号题' : '最多抽取 ' + form.wrongQuestionLimit + ' 道待销号题' }}（含已复核简答题），按整数分配为 {{ form.totalScore }} 分。每题至少1分；选入全部错题时若总分不足，发布前会提示提高总分。发布后题目固定不变。</p><small>没有符合范围的考试错题的学员不会收到本场考试；若没有任何学员可组卷，系统会阻止发布并提示原因。</small></div></section>
      <section v-else class="question-picker"><h3>从“{{ form.courseCode || '尚未选择课程' }}”题库选择试题</h3><p class="hint">展示所选章节的全部已启用题型。随机抽题用于客观题，简答题和大题可在下方手工选入并单独设置分值。</p><div class="filter-row"><select v-model="typeFilter" aria-label="题型筛选" @change="selectionPage = 1"><option value="">全部题型</option><option v-for="(label, value) in typeNames" :key="value" :value="value">{{ label }}</option></select><input v-model="search" class="search" placeholder="搜索本课程题干" aria-label="搜索题干" @input="selectionPage = 1" /></div>
        <div class="random-row"><label>单选题数（可用 {{ availableCount('SINGLE_CHOICE') }}）<input v-model.number="random.SINGLE_CHOICE" type="number" min="0" /></label><label>多选题数（可用 {{ availableCount('MULTIPLE_CHOICE') }}）<input v-model.number="random.MULTIPLE_CHOICE" type="number" min="0" /></label><label>判断题数（可用 {{ availableCount('TRUE_FALSE') }}）<input v-model.number="random.TRUE_FALSE" type="number" min="0" /></label><label>每题分值<input v-model.number="random.points" type="number" min="1" /></label><button type="button" class="secondary-button" @click="draw">随机抽题</button></div>
        <p v-if="form.courseCode && availableCount('MULTIPLE_CHOICE') === 0" class="question-pool-warning">当前课程暂无已启用的多选题。请先到 <RouterLink to="/questions">题库管理</RouterLink> 添加、Excel 导入，或把现有题目转换为多选题并启用。</p>
        <div class="selection-summary"><strong>已选 {{ selectedCount }} 道 · 合计 {{ totalPoints }} / {{ form.totalScore }} 分</strong><button v-if="selectedCount" type="button" class="link-button" @click="selected = {}">清空选择</button></div>
        <div v-if="!eligible.length" class="empty"><p>没有可用试题，请先到题库录入、审核并启用题目。</p></div><div v-else class="table-wrap"><table><thead><tr><th>选入</th><th>题型 / 编号</th><th>题干</th><th>分值</th></tr></thead><tbody><tr v-for="q in visible" :key="q.id"><td><input type="checkbox" :aria-label="'选择题目 ' + q.id" :checked="q.id in selected" @change="toggle(q.id, ($event.target as HTMLInputElement).checked)" /></td><td>{{ typeNames[q.type] }} #{{ q.id }}<br><span v-if="!randomTypes.includes(q.type as typeof randomTypes[number])" class="status-pill warning">人工判卷</span></td><td class="question-stem">{{ q.stem }}</td><td><input v-if="q.id in selected" v-model.number="selected[q.id]" :aria-label="'题目 ' + q.id + ' 分值'" class="points" type="number" min="1" required /><span v-else>—</span></td></tr></tbody></table></div>
        <div v-if="eligible.length" class="pagination"><button type="button" class="secondary-button" :disabled="selectionPage <= 1" @click="selectionPage--">上一页</button><span>{{ Math.min(selectionPage, pages) }} / {{ pages }}</span><button type="button" class="secondary-button" :disabled="selectionPage >= pages" @click="selectionPage++">下一页</button></div>
      </section><div class="actions"><button class="primary-button" :disabled="busy">{{ busy ? '保存中…' : '保存为草稿' }}</button><button type="button" class="secondary-button" @click="editorOpen = false">取消</button></div>
    </form>
  </article>
  <article class="panel table-panel"><div class="toolbar"><div><strong>考试列表</strong><small>{{ visibleExams.length }} 场考试，可分别发布不同课程</small></div><select v-model="examFilter" aria-label="筛选考试状态"><option value="">全部状态</option><option v-for="(label, value) in statusNames" :key="value" :value="value">{{ label }}</option></select></div><div v-if="loading" class="empty">正在加载考试…</div><div v-else-if="!visibleExams.length" class="empty"><h3>暂无考试</h3><p>创建考试、选择课程题库并发布后，考生即可参加。</p></div><div v-else class="table-wrap"><table><thead><tr><th>考试名称 / 课程</th><th>试卷规则</th><th>开放时间</th><th>作答次数</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="exam in visibleExams" :key="exam.id"><td><strong>{{ exam.title }}</strong><div class="exam-course">{{ exam.courseCode || '综合课程' }}</div><div v-if="exam.chapters?.length" class="chapter-line">范围：{{ exam.chapters.join('、') }}</div><div class="chapter-line">发布对象：{{ exam.audienceMode === 'USERS' ? '指定人员' : exam.audienceMode === 'MAJORS' ? '按专业' : '全员学员' }}</div><p class="hint">{{ exam.description }}</p></td><td><template v-if="exam.wrongQuestionPaper"><span class="paper-kind">个人错题卷</span><br />已覆盖 {{ exam.assignedCandidateCount || 0 }} 名学员 · {{ exam.allWrongQuestions ? '当前课程全部考试错题' : '每人最多 ' + exam.wrongQuestionLimit + ' 题' }}</template><template v-else>{{ exam.questionCount }} 题 · {{ exam.totalScore }} 分</template><br />{{ exam.durationMinutes }} 分钟 · {{ exam.passScore }} 分及格</td><td>{{ date(exam.startTime) }}<br />至 {{ date(exam.endTime) }}</td><td>每人一次</td><td><span class="tag" :class="{ muted: exam.status !== 'PUBLISHED' }">{{ statusNames[exam.status] }}</span></td><td class="nowrap"><template v-if="exam.status === 'DRAFT'"><button class="link-button" :disabled="busy" @click="edit(exam)">编辑</button><button v-if="canPublish" class="link-button" :disabled="busy" @click="action(exam, 'publish')">发布</button></template><template v-else><RouterLink class="link-button" :to="`/exams/${exam.id}/tracking`">应考追踪</RouterLink><RouterLink class="link-button" :to="'/results?examId=' + exam.id">成绩</RouterLink><button v-if="canPublish && ['PUBLISHED','CLOSED'].includes(exam.status)" class="link-button" :disabled="busy" @click="makeup(exam)">新建补考</button><button v-if="exam.status === 'PUBLISHED' && canPublish" class="link-button" :disabled="busy" @click="action(exam, 'close')">关闭</button><button v-if="exam.status === 'PUBLISHED' && canPublish" class="link-button" :disabled="busy" @click="cancelExam(exam)">取消考试</button></template></td></tr></tbody></table></div></article>
